describe('Dropdown Selection Test', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/dropdown');
  });

  it('should display disabled prompt and allow selection of an option', () => {
    // Verify initial state: disabled prompt is visible
    cy.get('[id="dropdown"]').should('be.visible');
    cy.get('[id="dropdown"]').should('contain', 'Please select an option');

    // Intercept the API call to get dropdown options
    cy.intercept('GET', '/api/dropdown-options').as('getDropdownOptions');

    // Verify dropdown is disabled
    cy.get('[id="dropdown"]').should('have.class', 'disabled');

    // Click on the dropdown to open
    cy.get('[id="dropdown"]').click();

    // Verify options are visible
    cy.get('[id="dropdown"]').should('not.have.class', 'disabled');
    cy.get('[id="dropdown"]').should('contain', '1=Option 1');
    cy.get('[id="dropdown"]').should('contain', '2=Option 2');

    // Select 'Option 2'
    cy.get('[id="dropdown"]').click();
    cy.get('[id="dropdown"]').should('contain', '2=Option 2');

    // Verify selection is applied
    cy.get('[id="dropdown"]').should('have.class', 'selected');
    cy.get('[id="dropdown"]').should('contain', '2=Option 2');

    // Verify value is set
    cy.get('[id="dropdown"]').should('have.attr', 'value', '2');

    // Verify prompt is no longer visible
    cy.get('[id="dropdown"]').should('not.contain', 'Please select an option');
  });

  it('should handle edge case when selecting disabled option', () => {
    // Verify initial state: disabled prompt is visible
    cy.get('[id="dropdown"]').should('be.visible');
    cy.get('[id="dropdown"]').should('contain', 'Please select an option');

    // Click on the dropdown to open
    cy.get('[id="dropdown"]').click();

    // Verify options are visible
    cy.get('[id="dropdown"]').should('not.have.class', 'disabled');

    // Attempt to select disabled option
    cy.get('[id="dropdown"]').click();
    cy.get('[id="dropdown"]').should('contain', 'Please select an option');

    // Verify prompt remains visible
    cy.get('[id="dropdown"]').should('contain', 'Please select an option');

    // Verify no selection is applied
    cy.get('[id="dropdown"]').should('not.have.attr', 'value');
    cy.get('[id="dropdown"]').should('not.contain', '2=Option 2');
  });
});
